import boto3

def upload_to_s3(bucket_name, file_path, object_name=None):
    if object_name is None:
        object_name = file_path
    s3_client = boto3.client('s3')
    try:
        response = s3_client.upload_file(file_path, bucket_name, object_name)
        print(f"Upload Successful: {object_name}")
    except Exception as e:
        print(e)
        raise

if __name__ == "__main__":
    bucket_name = 'your-bucket-name'
    file_path = 'path-to-your-file'
    upload_to_s3(bucket_name, file_path)

import boto3

def check_unsafe_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    return False

if __name__ == '__main__':
    sample_text = 'This is a sample text to check for unsafe content.'
    if check_unsafe_text(sample_text):
        print('The text contains unsafe content.')
    else:
        print('The text is safe.')

def static_image_request(image_path: str) -> dict:
    return {
        'image_path': image_path,
        'model': 'amazon-nova-api/nova-pro-v1'
    }


def visual_understanding_request(image_path: str, query: str) -> dict:
    return {
        'image_path': image_path,
        'query': query,
        'model': 'amazon-nova-api/nova-pro-v1'
    }


def normalize_response(response: dict) -> dict:
    return {
        'normalized_data': response.get('data', {})
    }
